#!/bin/bash
# Connect to QEMU serial console via nc
exec nc -U /root/qemu-run/serial.sock

#!/usr/bin/expect -f
set timeout 30
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@localhost "echo SSH_SUCCESS; id; uname -a"
expect {
    "password:" {
        send "password123\r"
        exp_continue
    }
    "SSH_SUCCESS" {
        puts "\n>>> SSH LOGIN WORKING <<<"
    }
    timeout {
        puts "\n>>> TIMEOUT <<<"
        exit 1
    }
    eof
}

#!/usr/bin/expect -f
set timeout 20
log_user 1
spawn ssh -v -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@localhost "echo SSH_SUCCESS_MARKER; id"
expect {
    -re "password:" {
        send "password123\r"
        exp_continue
    }
    "SSH_SUCCESS_MARKER" {
        puts "\n>>> SSH LOGIN WORKING <<<"
    }
    -re "Permission denied" {
        puts "\n>>> PERMISSION DENIED <<<"
    }
    timeout {
        puts "\n>>> TIMEOUT <<<"
        exit 1
    }
    eof
}
